let mapaCarpetas = {};

// Leemos las carpetas que ha bajado Outlook
for (let item of $input.all()) {
    if (item.json.displayName) {
        let nombreCarpeta = item.json.displayName.toUpperCase();
        mapaCarpetas[nombreCarpeta] = item.json.id;
    }
}

// Devolvemos el diccionario empaquetado para que el siguiente nodo lo pueda leer
return [{ json: { mapa: mapaCarpetas } }];

// 1. Llamamos directamente al diccionario usando el nombre del nodo que lo creó
const mapaCarpetas = $('Crear Diccionario').first().json.mapa;

// 2. Leemos la respuesta de la IA
let textoIA = $input.first().json.content.parts[0].text;
let correosClasificados = JSON.parse(textoIA);

// 3. Traducimos los nombres a IDs
for (let correo of correosClasificados) {
  correo.carpeta_id = mapaCarpetas[correo.carpeta] || mapaCarpetas["BANDEJA DE ENTRADA"] || mapaCarpetas["INBOX"]; 
}

return correosClasificados;

let lote_limpio = [];
let items = $input.all();

for (let item of items) {
    let correo = item.json;
    let correo_id = correo.id;

    // Extracción ultra-robusta del remitente
    let remitente = "Desconocido";

    if (typeof correo.sender === 'string') {
        // Por si n8n lo ha simplificado directamente a texto
        remitente = correo.sender;
    } else if (correo.sender && correo.sender.emailAddress && correo.sender.emailAddress.address) {
        // Estructura oficial de Microsoft Graph API
        remitente = correo.sender.emailAddress.address;
    } else if (correo.from && correo.from.emailAddress && correo.from.emailAddress.address) {
        // Alternativa en Graph API
        remitente = correo.from.emailAddress.address;
    } else if (correo.from && typeof correo.from === 'string') {
        remitente = correo.from;
    } else if (correo.senderAddress) {
        // Otra posible simplificación
        remitente = correo.senderAddress;
    }

    // Extracción del asunto
    let asunto = correo.subject || "Sin asunto";

    // Extracción del snippet
    let snippet = correo.bodyPreview || "";
    if (!snippet && correo.body && correo.body.content) {
        let cuerpo = correo.body.content.trim();
        snippet = cuerpo.length > 150 ? cuerpo.substring(0, 150) + "..." : cuerpo;
    }

    // Solo añadimos si hay un ID válido
    if (correo_id) {
        lote_limpio.push({
            id: correo_id,
            remitente: remitente,
            asunto: asunto,
            snippet: snippet
        });
    }
}

// Devolvemos todo agrupado en un solo ítem
return [{
    json: {
        total_correos: lote_limpio.length,
        datos_analisis: lote_limpio
    }
}];
